struct ClipboardDiffStrings {
    let title: String, subtitle: String, legend: String, missing: String, tooLarge: String, loading: String, identical: String
    let before: String, after: String
    static func localized(_ language: AppLanguage) -> Self {
        switch language {
        case .enUS: return .init(title: "Clipboard diff", subtitle: "Compare the two latest saved text copies", legend: "− Before    + After", missing: "Paste or edit both texts to compare them automatically.", tooLarge: "Each copy must fit within 200 KB and 2,000 lines. Nothing was truncated.", loading: "Comparing…", identical: "No differences", before: "Before", after: "After")
        case .ptBR: return .init(title: "Diferenças da área de transferência", subtitle: "Compare os dois últimos textos copiados e salvos", legend: "− Antes    + Depois", missing: "Cole ou edite os dois textos para comparar automaticamente.", tooLarge: "Cada cópia deve ter até 200 KB e 2.000 linhas. Nada foi truncado.", loading: "Comparando…", identical: "Sem diferenças", before: "Antes", after: "Depois")
        case .tr: return .init(title: "Pano farkları", subtitle: "Kaydedilen son iki metin kopyasını karşılaştır", legend: "− Önce    + Sonra", missing: "Otomatik karşılaştırmak için iki metni yapıştırın veya düzenleyin.", tooLarge: "Her kopya en fazla 200 KB ve 2.000 satır olmalıdır. Hiçbir şey kesilmedi.", loading: "Karşılaştırılıyor…", identical: "Fark yok", before: "Önce", after: "Sonra")
        case .ru: return .init(title: "Сравнение буфера обмена", subtitle: "Сравнить две последние сохранённые копии текста", legend: "− До    + После", missing: "Вставьте или измените оба текста для автоматического сравнения.", tooLarge: "Каждая копия должна содержать не более 200 КБ и 2 000 строк. Ничего не обрезано.", loading: "Сравнение…", identical: "Различий нет", before: "До", after: "После")
        case .es: return .init(title: "Diferencias del portapapeles", subtitle: "Compara los dos últimos textos copiados y guardados", legend: "− Antes    + Después", missing: "Pega o edita ambos textos para compararlos automáticamente.", tooLarge: "Cada copia debe tener como máximo 200 KB y 2.000 líneas. No se ha truncado nada.", loading: "Comparando…", identical: "Sin diferencias", before: "Antes", after: "Después")
        case .sk: return .init(title: "Rozdiely schránky", subtitle: "Porovnať posledné dve uložené kópie textu", legend: "− Pred    + Po", missing: "Vložte alebo upravte oba texty na automatické porovnanie.", tooLarge: "Každá kópia musí mať najviac 200 KB a 2 000 riadkov. Nič nebolo skrátené.", loading: "Porovnávanie…", identical: "Bez rozdielov", before: "Pred", after: "Po")
        case .de: return .init(title: "Zwischenablage vergleichen", subtitle: "Die letzten zwei gespeicherten Textkopien vergleichen", legend: "− Vorher    + Nachher", missing: "Beide Texte einfügen oder bearbeiten, um sie automatisch zu vergleichen.", tooLarge: "Jede Kopie darf höchstens 200 KB und 2.000 Zeilen enthalten. Nichts wurde gekürzt.", loading: "Vergleichen…", identical: "Keine Unterschiede", before: "Vorher", after: "Nachher")
        case .fr: return .init(title: "Comparer le presse-papiers", subtitle: "Comparer les deux derniers textes copiés et enregistrés", legend: "− Avant    + Après", missing: "Collez ou modifiez les deux textes pour les comparer automatiquement.", tooLarge: "Chaque copie doit tenir dans 200 Ko et 2 000 lignes. Rien n’a été tronqué.", loading: "Comparaison…", identical: "Aucune différence", before: "Avant", after: "Après")
        case .it: return .init(title: "Confronta appunti", subtitle: "Confronta le ultime due copie di testo salvate", legend: "− Prima    + Dopo", missing: "Incolla o modifica entrambi i testi per confrontarli automaticamente.", tooLarge: "Ogni copia deve rientrare in 200 KB e 2.000 righe. Nulla è stato troncato.", loading: "Confronto…", identical: "Nessuna differenza", before: "Prima", after: "Dopo")
        case .ja: return .init(title: "クリップボードの差分", subtitle: "保存された最新2件のテキストを比較", legend: "− 変更前    + 変更後", missing: "両方のテキストを貼り付けるか編集すると自動的に比較します。", tooLarge: "各コピーは200 KB・2,000行以内にしてください。内容は省略していません。", loading: "比較中…", identical: "差分なし", before: "変更前", after: "変更後")
        case .ko: return .init(title: "클립보드 비교", subtitle: "최근 저장된 두 텍스트 복사본 비교", legend: "− 변경 전    + 변경 후", missing: "두 텍스트를 붙여넣거나 편집하면 자동으로 비교합니다.", tooLarge: "각 복사본은 200 KB, 2,000줄 이하여야 합니다. 내용은 생략되지 않았습니다.", loading: "비교 중…", identical: "차이 없음", before: "변경 전", after: "변경 후")
        case .uk: return .init(title: "Порівняння буфера обміну", subtitle: "Порівняти дві останні збережені копії тексту", legend: "− До    + Після", missing: "Вставте або змініть обидва тексти для автоматичного порівняння.", tooLarge: "Кожна копія має містити не більше 200 КБ і 2 000 рядків. Нічого не обрізано.", loading: "Порівняння…", identical: "Відмінностей немає", before: "До", after: "Після")
        case .zhHans: return .init(title: "剪贴板差异", subtitle: "比较最近保存的两段复制文本", legend: "− 修改前    + 修改后", missing: "粘贴或编辑两段文本即可自动比较。", tooLarge: "每段文本不能超过 200 KB 和 2,000 行。内容未被截断。", loading: "正在比较…", identical: "没有差异", before: "修改前", after: "修改后")
        case .zhTW, .zhHK: return .init(title: "剪貼簿差異", subtitle: "比較最近儲存的兩段複製文字", legend: "− 修改前    + 修改後", missing: "貼上或編輯兩段文字即可自動比較。", tooLarge: "每段文字不能超過 200 KB 和 2,000 行。內容未被截斷。", loading: "正在比較…", identical: "沒有差異", before: "修改前", after: "修改後")
